from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('P11','Classificare nuove stazioni sintetiche','Separazione dei dati, standardizzazione e classificatore dei centroidi')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('P11',i,b)
m.sezione_nuova('Bersaglio e protocollo di valutazione')
p('La classe viene prevista da cinque caratteristiche',
'''Il progetto assegna ciascun campione a una delle tre litologie sintetiche, Arenaria, Basalto e Calcare, utilizzando quattro composizioni in ossidi e la densità. Il campione comprende centottanta provini raccolti in diciotto stazioni simulate. La domanda riguarda il trasferimento a stazioni escluse dall’adattamento, per cui la separazione segue l’identità territoriale anziché i singoli provini. Il caso riutilizza dati già incontrati nel percorso didattico e applica una procedura prefissata; il risultato non costituisce una valutazione finale inedita di un modello scelto dopo ripetuti confronti.''',tikz=d('D01',rect(.6,.7,6.8,2.3)+n(3.7,1.5,r'$\mathrm{SiO}_2$, CaO, MgO, FeO e densità',w=5.8,size=13)+a(3.7,2.6,3.7,3.3)+rect(1.2,3.6,6.2,5.1,'Quantum')+n(3.7,4.35,'Regola di classificazione',w=4.7,size=13)+n(3.7,6,'Tre classi note del generatore sintetico.',w=6.8,size=11.5)),richiamo='Il protocollo di valutazione deve corrispondere al tipo di nuova unità sulla quale si intende applicare il modello.',origine='P11:1–4')
p('La stazione resta interamente in un insieme',
'''Quindici stazioni, con centocinquanta campioni, appartengono all’adattamento; le tre restanti, con trenta campioni, costituiscono il test. Nessuna stazione compare in entrambi gli insiemi. La divisione conserva dieci provini per stazione e, nel test, una stazione per ciascuna classe. Il controllo dell’intersezione degli identificativi territoriali verifica quindi una condizione più forte della semplice assenza di righe duplicate, evitando che provini dello stesso gruppo forniscano informazione sia alla costruzione sia alla valutazione della regola.''',formula=r'\mathcal S_{train}\cap\mathcal S_{test}=\varnothing',figura='P11/F01',didascalia='Cinquanta campioni train e dieci test per classe; stazioni disgiunte.',richiamo='La separazione per gruppi conserva il livello al quale si vuole valutare la generalizzazione.',origine='P11:5–7')
c=estratto('P11','separazione',"d <- read.csv('dati/ml_v3.csv')\ntr <- d$split=='train'\nte <- d$split=='test'\nstopifnot(sum(tr)==150,sum(te)==30,\n length(intersect(d$stazione[tr],\n d$stazione[te]))==0)\ntable(d$litologia,d$split)")
p('Il controllo conserva la struttura della divisione',
'''Il frammento ricostruisce i due insiemi dalla variabile di appartenenza già presente nei dati e ne verifica numerosità e disgiunzione delle stazioni. La tabella per litologia rende inoltre esplicito il bilanciamento delle classi. Il controllo precede standardizzazione e calcolo dei centroidi, affinché nessuna statistica della risposta o dei predittori del test entri nella costruzione della regola. Le etichette del test verranno utilizzate soltanto dopo aver prodotto le classificazioni con il procedimento definito.''',codice=c,richiamo='La divisione deve precedere ogni trasformazione che apprende parametri dai dati.',origine='P11:6–7')
p('Il riferimento risolve un pareggio dichiarato',
'''La procedura elementare assegna a tutti i nuovi campioni la classe più frequente nell’adattamento. Poiché le tre classi hanno cinquanta osservazioni ciascuna, il pareggio viene risolto secondo l’ordine alfabetico e la previsione costante diventa Arenaria. Nel test bilanciato questa regola classifica correttamente dieci campioni su trenta, con accuratezza pari a un terzo. Il riferimento quantifica così la prestazione ottenibile senza usare le caratteristiche e rende interpretabile il contributo del classificatore successivo.''',formula=r'\widehat c_0=\arg\max_c n_{c,train},\qquad Acc_0=\frac{10}{30}',tikz=d('D02',rect(.6,.7,6.8,2)+n(3.7,1.35,'50 Arenaria, 50 Basalto, 50 Calcare',w=6,size=12)+a(3.7,2.3,3.7,3)+rect(.6,3.3,6.8,4.6,'Quantum')+n(3.7,3.95,'Pareggio: ordine alfabetico',w=6,size=12)+n(3.7,5.7,'Previsione costante: Arenaria.',w=6.8,size=13)),richiamo='Anche la procedura di riferimento deve essere definita usando esclusivamente l’insieme di adattamento.',origine='P11:8–10')
m.sezione_nuova('Geometria standardizzata e centroidi')
p('La standardizzazione apprende soltanto dal train',
'''Le composizioni e la densità hanno scale numeriche differenti, che influenzerebbero direttamente una distanza euclidea. Ogni variabile viene quindi centrata sulla propria media nell’adattamento e divisa per la deviazione standard dello stesso insieme, calcolata con denominatore n meno uno. Questi parametri vengono conservati e applicati senza ricalcolo ai trenta campioni di test. La trasformazione stabilisce la metrica del classificatore; includere il test nel calcolo delle scale introdurrebbe informazione del campione di verifica nella procedura da valutare.''',formula=r'z_{ij}=\frac{x_{ij}-\overline x_{j,train}}{s_{j,train}}',destra='Le medie standardizzate del train sono nulle e le sue deviazioni standard sono unitarie entro la tolleranza numerica. Queste proprietà non sono richieste nel test, le cui differenze possono riflettere una distribuzione diversa nelle stazioni escluse.',richiamo='I parametri della trasformazione fanno parte del modello appreso e devono essere conservati insieme al classificatore.',origine='P11:11–13')
p('Il centroide rappresenta la media di una classe',
'''Per ciascuna litologia si calcola il vettore medio delle cinque caratteristiche standardizzate nei soli campioni di adattamento. La carta cromatica mostra i tre centroidi, consentendo di riconoscere quali variabili caratterizzino la posizione media dei gruppi nel generatore sintetico. Il colore esprime deviazioni standard rispetto alla media complessiva del train. Un centroide riassume la posizione della classe e lascia esclusa la sua dispersione interna, che potrebbe diventare rilevante quando gruppi differenti mostrano forme o varianze molto diverse.''',formula=r'\mathbf c_k=\frac1{n_{k,train}}\sum_{i\in train:Y_i=k}\mathbf z_i',figura='P11/F03',didascalia='Colonne: SiO₂, CaO, MgO, FeO e densità (ρ).',richiamo='La geometria del centroide riassume la posizione media, senza modellare l’intera distribuzione della classe.',origine='P11:11–13')
p('La regola minimizza una distanza quadratica',
'''Un nuovo vettore standardizzato viene assegnato al centroide più vicino nella metrica euclidea a cinque dimensioni. Poiché la radice quadrata conserva l’ordine, il codice confronta direttamente le somme dei quadrati degli scarti. L’eventuale pareggio segue l’ordine alfabetico dichiarato delle classi. La decisione dipende quindi da scale, centroidi e convenzione di assegnazione, che devono essere tutti disponibili per riprodurre la previsione su un nuovo campione.''',formula=r'\widehat y(\mathbf z)=\arg\min_k\sum_{j=1}^{5}(z_j-c_{kj})^2',tikz=d('D03',linea(.7,5.3,6.7,5.3)+linea(.7,5.3,.7,.7)+n(2.1,2,r'$\mathbf c_A$',size=15,color='Classical')+n(5.4,3.8,r'$\mathbf c_B$',size=15,color='Quantum')+n(3.6,2.7,r'$\mathbf z$',size=16)+linea(2.4,2.15,3.3,2.55,'Classical')+linea(3.9,2.9,5,3.6,'Quantum')+n(3.7,6,'Schema in due dimensioni; calcolo effettivo in cinque.',w=6.8,size=10.8)),richiamo='La regola di classificazione è definita nello spazio trasformato, la cui metrica dipende dalle scale apprese.',origine='P11:11–13')
p('Il confine fra due centroidi è un iperpiano',
'''Le osservazioni equidistanti da due centroidi soddisfano l’uguaglianza fra le due distanze quadratiche. Espandendo i quadrati, il termine comune nella norma dell’osservazione si elimina e rimane un’equazione lineare nel vettore standardizzato. Il confine è quindi un iperpiano, che diventa una retta in una rappresentazione bidimensionale. Con tre classi, ciascuna regione è determinata dal confronto simultaneo con gli altri centroidi; la struttura risultante dipende dalla metrica scelta e dalle posizioni delle medie di classe.''',formula=r'2\mathbf z^T(\mathbf c_b-\mathbf c_a)=\|\mathbf c_b\|^2-\|\mathbf c_a\|^2',destra='La derivazione mostra perché un classificatore dei centroidi produce confini lineari fra coppie di classi. Trasformazioni delle scale modificano le distanze e possono quindi cambiare tali confini nello spazio delle variabili originarie.',richiamo='La forma del confine deriva dalla regola matematica di distanza e non deve essere dedotta soltanto da una proiezione grafica.',origine='P11:11–13')
p('La proiezione conserva soltanto due coordinate',
'''Il diagramma rappresenta silice e ossido di calcio standardizzati, con punti per il train, triangoli per il test e croci per i centroidi. La separazione visibile aiuta a comprendere la struttura del campione sintetico, ma il classificatore utilizza anche magnesio, ferro e densità. La figura è dunque una proiezione del problema e non rappresenta tutte le distanze né i confini effettivi della decisione. Una sovrapposizione in questa vista potrebbe scomparire nello spazio completo, mentre una separazione apparente richiede comunque verifica numerica.''',figura='P11/F02',didascalia='Proiezione SiO₂–CaO: train, test e centroidi; decisione in cinque dimensioni.',richiamo='Una proiezione grafica illustra la geometria senza sostituire il calcolo nello spazio completo dei predittori.',origine='P11:11–16')
m.sezione_nuova('Prestazione e limiti dell’interpretazione')
c=estratto('P11','previsione',"d <- read.csv('dati/ml_v3.csv')\nm <- readRDS('risultati/P11/centroidi_modello.rds')\nte <- d$split=='test'\nZ <- scale(d[te,m$variabili],\n center=m$centro,scale=m$scala)\nD <- sapply(m$classi,function(k)\n rowSums(sweep(Z,2,m$centroidi[k,],'-')^2))\np <- m$classi[max.col(-D,ties.method='first')]\ntable(osservata=d$litologia[te],prevista=p)")
p('Il modello conservato ricostruisce le decisioni',
'''Il file del modello contiene nomi e ordine delle variabili, medie, scale, centroidi e classi. Il frammento rilegge questi oggetti e calcola le previsioni senza stimare nuovi parametri, rendendo esplicito il passaggio dall’adattamento all’applicazione. Le classi osservate entrano soltanto nella tabella finale di confronto. La rilettura viene verificata rispetto all’oggetto salvato, poiché una ricostruzione parziale che omettesse l’ordine delle colonne potrebbe produrre distanze errate anche usando gli stessi valori numerici.''',codice=c,richiamo='Riprodurre una decisione richiede l’intera trasformazione e l’ordine delle caratteristiche, oltre ai soli centroidi.',origine='P11:12–16')
p('La matrice di confusione conserva i conteggi',
'''Tutti i trenta campioni di test vengono assegnati alla classe osservata, con dieci casi sulla diagonale per ciascuna litologia. L’accuratezza risulta quindi pari a uno in questo campione. La matrice conserva i denominatori e rende controllabile l’assenza di errori fra coppie di classi, senza trasformare l’esito in una garanzia universale. I trenta provini provengono soltanto da tre stazioni e dallo stesso generatore sintetico, condizioni che limitano l’interpretazione rispetto a un’applicazione su rocce reali.''',formula=r'Acc=\frac1{30}\sum_{i\in test}\mathbf1\{\widehat y_i=y_i\}=1',figura='P11/F04',didascalia='Are.: Arenaria; Bas.: Basalto; Cal.: Calcare. Conteggi osservato–previsto.',richiamo='Un’accuratezza perfetta nel campione disponibile non dimostra assenza di errore nella popolazione di applicazione.',origine='P11:14–16')
p('Il confronto quantifica il contributo delle variabili',
'''L’accuratezza passa da un terzo per la previsione costante a uno per il classificatore dei centroidi. Entrambe le procedure sono valutate sugli stessi trenta campioni, così che il confronto conservi il medesimo denominatore. Il guadagno è coerente con la separazione costruita nel generatore sintetico e dimostra il funzionamento del procedimento didattico. L’impiego su nuove stazioni reali richiederebbe dati indipendenti, verifiche delle unità e valutazione delle differenze fra distribuzione di adattamento e contesto operativo.''',figura='P11/F05',didascalia='Accuratezze sullo stesso test: riferimento costante e centroidi.',richiamo='La prestazione viene attribuita alla procedura e alla distribuzione effettivamente valutate.',origine='P11:14–18')
p('Il margine misura una separazione geometrica',
'''La differenza fra la seconda distanza quadratica più piccola e la prima misura quanto la decisione sia separata dalla classe concorrente più vicina. Nel campione tutti i margini sono positivi, coerentemente con assegnazioni senza pareggio. La distribuzione per classe descrive la geometria del classificatore e può aiutare a individuare decisioni più prossime al confine. Il margine non è una probabilità calibrata di correttezza e potrebbe essere ampio anche per un campione esterno al dominio rappresentato dalle tre classi note.''',formula=r'\Delta_i=d^2_{i,(2)}-d^2_{i,(1)}',figura='P11/F06',didascalia='Margini quadratici nel test, distinti per classe osservata.',richiamo='La distanza dal concorrente misura una proprietà geometrica; la probabilità di errore richiede una valutazione ulteriore.',origine='P11:17–19')
m.sezione_nuova('Scheda del modello e consegna')
p('La scheda conserva dominio e condizioni d’uso',
'''La scheda del modello registra bersaglio, origine sintetica, variabili e unità, numerosità per insieme, regola di standardizzazione, metrica, accuratezza e limiti. Il file JSON accompagna l’oggetto RDS e permette di interpretarlo senza ricostruire tutte le operazioni del laboratorio. La scheda dichiara inoltre il riuso didattico del test, l’assenza di validazione su rocce reali e l’impossibilità di riconoscere automaticamente classi non incluse nell’adattamento. Un campione nuovo richiede quindi anche una verifica di pertinenza al dominio.''',tikz=d('D04',rect(.6,.6,6.8,2)+n(3.7,1.3,'Variabili, unità e trasformazione',w=5.8,size=12)+rect(.6,2.5,6.8,3.9,'Quantum')+n(3.7,3.2,'Dati di valutazione e prestazione',w=5.8,size=12)+rect(.6,4.4,6.8,5.8)+n(3.7,5.1,'Dominio, limiti e versioni',w=5.8,size=12)),richiamo='Il modello conservato deve essere accompagnato dalle condizioni entro le quali la sua prestazione è stata osservata.',origine='P11:17–20')
p('Consegna: collegare geometria e validazione',
'''La relazione presenta separazione delle stazioni, riferimento costante, standardizzazione, centroidi, matrice di confusione e scheda del modello. L’esercizio richiede di derivare il confine fra due centroidi e di spiegare perché medie e scale debbano essere stimate soltanto sul train. La discussione finale chiarisce perché trenta classificazioni corrette, provenienti da tre stazioni sintetiche, non siano sufficienti a dimostrare affidabilità generale. La conclusione distingue il risultato del caso didattico dalle evidenze ancora necessarie per un’applicazione geologica reale.''',destra='R/P11_figure.R integra separazione, riferimento, classificatore e scheda. Il modello serializzato, i parametri di standardizzazione e le previsioni per identificativo sono conservati in risultati/P11. Il raccordo con M16 permette di approfondire validazione a gruppi, scelta dei modelli e calibrazione.',richiamo='La generalizzazione viene sostenuta dal disegno della verifica e dalla pertinenza dei dati al contesto di applicazione.',origine='P11:17–20')
m.salva()
